competencyQuestions.sparql:
SELECT ?identicality
WHERE {
  ?identicality a fs:Identicality ;
               parameter:hasParameterDataValue false. }

SELECT ?EventOutcome ?ProbabilityLevel
WHERE {
    ?event dbo:produces ?EventOutcome.
    ?event parameter:hasParameter ?Probability.
    ?Probability parameter:hasParameterDataValue. 
    FILTER (
        CONTAINS(LCASE(STR(?EventOutcome)), "red") &&
        (LCASE(?ProbabilityLevel) = "high")
    )
}

SELECT ? stimulus
            WHERE {?activity rdf:type fs:Activity;
                           cbo:involves ?Stimulus.
}

SELECT ?element
WHERE {?person rdf:type fs:People;
                                   cbo:isBiasedBy ?element.
            ?element cbo:hasInfluence ?perception.
            ?perception rdf:type fs:PerceptionExperience.
}

SELECT ?entity
WHERE {
?entity a cbo:Non-humanEntity.
?perception a fs:PerceptionExperience.
?perception cbo:involves ?entity. }
